36	     * 2. none of the group policies they are a member of have isPolicyExpenseChatEnabled=true
37	     */
38	    const [shouldRedirectToExpensifyClassic = false] = useOnyx(ONYXKEYS.COLLECTION.POLICY, {selector: shouldRedirectToExpensifyClassicSelector});
39	
40	    const showRedirectToExpensifyClassicModal = async () => {
41	        const {action} = await showConfirmModal({
42	            title: translate('sidebarScreen.redirectToExpensifyClassicModal.title'),
43	            prompt: translate('sidebarScreen.redirectToExpensifyClassicModal.description'),
44	            confirmText: translate('exitSurvey.goToExpensifyClassic'),
45	            cancelText: translate('common.cancel'),
46	        });
47	        if (action !== ModalActions.CONFIRM) {
48	            return;
49	        }
50	        if (CONFIG.IS_HYBRID_APP) {
51	            closeReactNativeApp({shouldSetNVP: true, isTrackingGPS});
52	            return;
53	        }
54	        openOldDotLink(CONST.OLDDOT_URLS.INBOX);
55	    };
56	
57	    return {shouldRedirectToExpensifyClassic, showRedirectToExpensifyClassicModal};
58	}
