import type {TryNewDot} from '@src/types/onyx';
import {isEmptyObject} from '@src/types/utils/EmptyObject';

/**
 * Determines whether the user should be redirected to the old app (OldDot / Expensify Classic).
 *
 * Mobile-locked users (`isLockedToNewApp === true`) must always stay in NewApp, so this returns
 * `false` for them regardless of the `classicRedirect.dismissed` value. For unlocked users we fall
 * back to the existing classic redirect logic.
 */
function shouldUseOldApp(tryNewDot: TryNewDot): boolean | undefined {
    if (tryNewDot?.isLockedToNewApp) {
        return false;
    }
    if (isEmptyObject(tryNewDot) || isEmptyObject(tryNewDot.classicRedirect)) {
        return true;
    }
    return tryNewDot.classicRedirect.dismissed;
}

/**
 * Determines whether the redirect to the old app is blocked because the user is administratively
 * locked into NewApp. The mobile lock is only respected when `shouldRespectMobileLock` is true
 * (e.g. on HybridApp), so on web (`shouldRespectMobileLock === false`) this always returns false.
 */
function isOldAppRedirectBlocked(tryNewDot: OnyxEntry<TryNewDot>, shouldRespectMobileLock: boolean): boolean {
    return shouldRespectMobileLock && !!tryNewDot?.isLockedToNewApp;
}

/**
 * Determines whether the old app redirect UI should be hidden. It is hidden while the lock state is
 * still loading in a mobile-respecting context, or when the redirect is blocked by the mobile lock.
 * When the mobile lock is not respected (e.g. web) the redirect is never hidden by this logic.
 */
function shouldHideOldAppRedirect(tryNewDot: OnyxEntry<TryNewDot>, isLoadingTryNewDot: boolean, shouldRespectMobileLock: boolean): boolean {
    if (shouldRespectMobileLock && isLoadingTryNewDot) {
        return true;
    }
    return isOldAppRedirectBlocked(tryNewDot, shouldRespectMobileLock);
}

/**
 * Determines whether an old-app exit action should be blocked.
 *
 * - Always blocks when the user is locked into NewApp (`isLockedToNewApp === true`).
 * - Otherwise blocks NVP-setting exits (`shouldSetNVP === true`) while the lock state is still
 *   resolving (`isLoadingTryNewDot === true`), so we don't let a locked user out before we know
 *   they are locked.
 */
function shouldBlockOldAppExit(tryNewDot: OnyxEntry<TryNewDot>, isLoadingTryNewDot: boolean, shouldSetNVP: boolean): boolean {
    if (tryNewDot?.isLockedToNewApp) {
        return true;
    }
    return isLoadingTryNewDot && shouldSetNVP;
}

export {shouldUseOldApp, isOldAppRedirectBlocked, shouldHideOldAppRedirect, shouldBlockOldAppExit};
